enum SubcardOnlineE {
  /** 子卡不在线，即子卡被拔掉 */
  pullOut = 0,
  /** 子卡在线（正常状态，默认值，升级时只能升级当前状态的子卡） */
  online = 1,
  /** 子卡插上了，但是与主控链接异常 */
  warning = 2,
  /** 本设备不支持的子卡类型（如D系列设备插上了F系列的卡） */
  notSupported = 3,
  /** 不同类型的子卡混插，如输入卡插在了输出槽位） */
  wrong = 4,
  /** 子卡在线单子卡版本和设备程序版本不匹配 */
  versionMismatch = 5,
  /** 热插拔 插入新卡后子卡异常状态 */
  abnormal = 6,
  /** 子卡正在准备中 */
  loading = 7,
}
